#[derive(Parser, Debug)]
#[command(name = "onefetch", version = "2.25.0", about = "Command-line Git information tool", 
    long_about = None,
    disable_help_flag = true,
    disable_version_flag = true,
)]
struct Cli {
    #[arg(value_name = "INPUT", help = "Run as if onefetch was started in <input> instead of the current working directory")]
    input: Option<String>,

    #[arg(short = 'h', long = "help", action = ArgAction::Help, help = "Print help (see a summary with '-h')")]
    help_flag: Option<bool>,

    #[arg(short = 'V', long = "version", action = ArgAction::Version, help = "Print version")]
    version_flag: Option<bool>,

    // INFO
    #[arg(short = 'd', long = "disabled-fields", value_name = "FIELD", num_args = 1.., value_parser = parse_disabled_field, help = "Allows you to disable FIELD(s) from appearing in the output")]
    disabled_fields: Vec<String>,

    #[arg(long = "no-title", help = "Hides the title")]
    no_title: bool,

    #[arg(long = "number-of-authors", value_name = "NUM", default_value = "3", help = "Maximum NUM of authors to be shown")]
    number_of_authors: usize,

    #[arg(long = "number-of-languages", value_name = "NUM", default_value = "6", help = "Maximum NUM of languages to be shown")]
    number_of_languages: usize,

    #[arg(long = "number-of-file-churns", value_name = "NUM", default_value = "3", help = "Maximum NUM of file churns to be shown")]
    number_of_file_churns: usize,

    #[arg(long = "churn-pool-size", value_name = "NUM", help = "Minimum NUM of commits from HEAD used to compute the churn summary")]
    churn_pool_size: Option<usize>,

    #[arg(short = 'e', long = "exclude", value_name = "EXCLUDE", num_args = 1.., help = "Ignore all files & directories matching EXCLUDE")]
    exclude: Vec<String>,

    #[arg(long = "no-bots", value_name = "REGEX", num_args = 0..=1, default_missing_value = "", help = "Exclude [bot] commits. Use <REGEX> to override the default pattern")]
    no_bots: Option<String>,

    #[arg(long = "no-merges", help = "Ignores merge commits")]
    no_merges: bool,

    #[arg(short = 'E', long = "email", help = "Show the email address of each author")]
    email: bool,

    #[arg(long = "http-url", help = "Display repository URL as HTTP")]
    http_url: bool,

    #[arg(long = "hide-token", help = "Hide token in repository URL")]
