// parsers for validation to match original error messages
fn parse_disabled_field(s: &str) -> Result<String, String> {
    let allowed = ["project","description","head","pending","version","created","languages","dependencies","authors","last-change","contributors","url","commits","churn","lines-of-code","size","license"];
    if allowed.contains(&s) {
        Ok(s.to_string())
    } else {
        Err(format!("invalid value '{}' for '--disabled-fields <FIELD>...'\n  [possible values: {}]\n\nFor more information, try '--help'.", s, allowed.join(", ")))
    }
}
fn parse_type(s: &str) -> Result<String, String> {
    let allowed = ["programming","markup","prose","data"];
    if allowed.contains(&s) {
        Ok(s.to_string())
    } else {
        Err(format!("invalid value '{}' for '--type <TYPE>...'\n  [possible values: programming, markup, prose, data]\n\nFor more information, try '--help'.", s))
    }
}
