fn get_dependencies(repo_root: &Path, dominant: &PackageManager) -> String {
    match dominant {
        PackageManager::Cargo => {
            if let Some(cnt) = read_cargo_deps(repo_root) {
                return format!("{} (Cargo)", cnt);
            }
            if let Some(cnt) = read_npm_deps(repo_root) {
                return format!("{} (Npm)", cnt);
            }
            "".to_string()
        },
        PackageManager::Npm => {
            if let Some(cnt) = read_npm_deps(repo_root) {
                return format!("{} (Npm)", cnt);
            }
            if let Some(cnt) = read_cargo_deps(repo_root) {
                return format!("{} (Cargo)", cnt);
            }
            "".to_string()
        },
        PackageManager::None => "".to_string(),
    }
}
fn read_cargo_deps(repo_root: &Path) -> Option<usize> {
    let cargo_path = repo_root.join("Cargo.toml");
    if !cargo_path.exists() { return None; }
    let content = fs::read_to_string(cargo_path).ok()?;
    // find [dependencies] section
    let mut count = 0;
    let mut in_deps = false;
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("[dependencies]") {
            in_deps = true;
            continue;
        }
        if trimmed.starts_with("[") {
            if in_deps {
                break;
            }
            in_deps = false;
        }
        if in_deps {
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            if trimmed.contains('=') {
                count += 1;
            }
        }
    }
    if count >0 { Some(count) } else { None }
}
fn read_npm_deps(repo_root: &Path) -> Option<usize> {
    let npm_path = repo_root.join("package.json");
    if !npm_path.exists() { return None; }
    let content = fs::read_to_string(npm_path).ok()?;
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    if let Some(deps) = v.get("dependencies").and_then(|d| d.as_object()) {
        let cnt = deps.len();
        if cnt>0 { return Some(cnt); }
    }
    None
}

fn get_head_info(repo: &Repository) -> HeadInfo {
    let head = repo.head().ok();
    let commit_id = if let Ok(r) = repo.revparse_single("HEAD") {
        let oid = r.id();
        let s = oid.to_string();
        s[..7].to_string()
    } else {
        "0000000".to_string()
    };
    let refs = if let Some(head_ref) = head {
        if head_ref.is_branch() {
            if let Some(name) = head_ref.shorthand() {
                vec![name.to_string()]
            } else {
                vec![]
            }
        } else {
            // detached HEAD
            vec![]
        }
    } else {
        vec![]
    };
    HeadInfo {
        headRefs: HeadRefs {
            shortCommitId: commit_id,
            refs,
        }
    }
}

fn get_pending_info(repo: &Repository) -> PendingInfo {
    let repo_path = repo.path().parent().unwrap();
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("status")
        .arg("--porcelain")
        .output();
    let mut added = 0;
    let mut deleted = 0;
    let mut modified = 0;
    if let Ok(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            if line.starts_with("??") {
                added += 1;
            } else {
                if line.len() >=2 {
                    let chars: Vec<char> = line.chars().collect();
                    let second = chars[1];
                    if second == 'M' {
                        modified +=1;
                    } else if second == 'D' {
                        deleted +=1;
                    }
                }
            }
        }
    }
    PendingInfo { added, deleted, modified }
}

fn get_created_last_change(repo: &Repository) -> (DateTime<Utc>, DateTime<Utc>) {
    // git log --format=%ct reverse
    let repo_path = repo.path().parent().unwrap();
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("log")
        .arg("--reverse")
        .arg("--format=%ct")
        .output();
    let mut timestamps = Vec::new();
    if let Ok(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            if let Ok(ts) = line.trim().parse::<i64>() {
                timestamps.push(ts);
            }
        }
    }
    if timestamps.is_empty() {
        let now = Utc::now();
        return (now, now);
    }
    let first = timestamps[0];
    let last = *timestamps.last().unwrap();
    let created = Utc.timestamp_opt(first, 0).unwrap();
    let last_change = Utc.timestamp_opt(last, 0).unwrap();
    (created, last_change)
}

fn format_relative_time(dt: DateTime<Utc>) -> String {
    let now = Utc::now();
    let duration = now.signed_duration_since(dt);
    let secs = duration.num_seconds();
    if secs < 0 {
        return "now".to_string();
    }
    if secs < 45 {
        return "now".to_string();
    }
    if secs < 90 {
        return "a minute ago".to_string();
    }
    if secs < 45*60 {
        let mins = secs / 60;
        return format!("{} minutes ago", mins);
    }
    if secs < 90*60 {
        return "an hour ago".to_string();
    }
    if secs < 22*3600 {
        let hours = secs / 3600;
        return format!("{} hours ago", hours);
    }
    if secs < 36*3600 {
        return "a day ago".to_string();
    }
    if secs < 6*24*3600 {
        let days = secs / (24*3600);
        return format!("{} days ago", days);
    }
    if secs < 11*24*3600 {
        return "a week ago".to_string();
    }
    if secs < 25*24*3600 {
        let weeks = secs / (7*24*3600);
        return format!("{} weeks ago", weeks);
    }
    if secs < 45*24*3600 {
        return "a month ago".to_string();
    }
    if secs < 345*24*3600 {
        let months = secs / (30*24*3600);
        if months <=1 {
            return "a month ago".to_string();
        } else {
            return format!("{} months ago", months);
        }
    }
    if secs < 545*24*3600 {
        return "a year ago".to_string();
    }
    let years = secs / (365*24*3600);
    if years <=1 {
        "a year ago".to_string()
    } else {
        format!("{} years ago", years)
    }
}

fn get_languages_info(repo_root: &Path, cli: &Cli) -> Option<LanguagesInfo> {
    // Walk files, respecting exclude and include_hidden
    let files = collect_files(repo_root, cli);
    // Map extension to language
    let mut lang_bytes: HashMap<String, usize> = HashMap::new();
    // Also need loc per file for percentage based on loc? Or based on file count? In earlier test, percentage was based on ??? For repo with a.py 2 lines and b.js 1 line, percentages 66.6 and 33.3 based on lines? Yes Python 2 lines vs JS 1 line => 66.6 vs 33.3. So percentage based on loc.

    // For each file, detect language, count loc (simple non-empty lines), accumulate bytes? Actually loc for percentage.
    let mut lang_loc: HashMap<String, usize> = HashMap::new();

    for file_path in files {
        if let Some(lang) = detect_language(&file_path) {
            // Check type filter
            let lang_type = get_language_type(&lang);
            if !cli.type_filter.contains(&lang_type) {
                continue;
            }
            // Count loc
            if let Ok(content) = fs::read_to_string(&file_path) {
                let loc = content.lines().filter(|l| !l.trim().is_empty()).count();
                // For simplicity, count all non-empty as loc
                *lang_loc.entry(lang.clone()).or_insert(0) += loc;
            }
        }
    }

    if lang_loc.is_empty() {
        return None;
    }

    let total_loc: usize = lang_loc.values().sum();
    let mut percentages: Vec<LanguagePercentage> = Vec::new();
    for (lang, loc) in lang_loc {
        let perc = if total_loc >0 {
            (loc as f64 / total_loc as f64) * 100.0
        } else { 0.0 };
        percentages.push(LanguagePercentage { language: lang, percentage: perc });
    }
    // Sort by percentage descending
    percentages.sort_by(|a,b| b.percentage.partial_cmp(&a.percentage).unwrap());
    // Limit by number_of_languages
    let limited = percentages.into_iter().take(cli.number_of_languages).collect();
    Some(LanguagesInfo { languagesWithPercentage: limited })
}

fn collect_files(repo_root: &Path, cli: &Cli) -> Vec<PathBuf> {
    let mut files = Vec::new();
    // Use git ls-files to get tracked files
    let repo_path = repo_root;
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("ls-files")
        .output();
    if let Ok(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let file_path = repo_path.join(line);
            if !file_path.exists() { continue; }
            // Check hidden
            if !cli.include_hidden {
                // if any component starts with '.' => skip
                let mut is_hidden = false;
                for comp in file_path.components() {
                    if let Some(s) = comp.as_os_str().to_str() {
                        if s.starts_with('.') && s != "." && s != ".." {
                            is_hidden = true;
                            break;
                        }
                    }
                }
                if is_hidden { continue; }
            }
            // Check exclude patterns (simple glob)
            let mut excluded = false;
            for pattern in &cli.exclude {
                // Use glob matching
                // pattern may be like "*.rs" or "src/*"
                // We'll use glob crate matching against relative path
                let rel = file_path.strip_prefix(repo_path).unwrap_or(&file_path);
                let rel_str = rel.to_string_lossy();
                // simple matching: if pattern contains *, use glob, else substring
                if pattern.contains('*') {
                    if glob::Pattern::new(pattern).map(|p| p.matches(&rel_str) || p.matches(file_path.file_name().unwrap_or_default().to_string_lossy().as_ref())).unwrap_or(false) {
                        excluded = true;
                        break;
                    }
                } else {
                    if rel_str.contains(pattern) {
                        excluded = true;
                        break;
                    }
                }
            }
            if excluded { continue; }
            files.push(file_path);
        }
    } else {
        // fallback walkdir
        for entry in walkdir::WalkDir::new(repo_path).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                let p = entry.path();
                if p.to_string_lossy().contains(".git") { continue; }
                files.push(p.to_path_buf());
            }
        }
    }
    files
}

