                    // Format similar to original: "1+ - 1+ 1-" ??? Actually original pending text format: for added 1 deleted 1 modified 1, it showed "1+ - 1+ 1-"? Let's check earlier: for pendingtest with added 1 deleted 1 modified 1, output was "1+- 1+ 1-"? Actually we saw "1+- 1+ 1-" is weird. Let's look: for /tmp/pendingtest earlier text showed "1+- 1+ 1-"? Actually we had output: "Pending: 1+- 1+ 1-". Wait original pending output for /tmp/pendingtest with added 1 deleted 1 modified 1 gave "1+- 1+ 1-"? Let's check again.

                    // For simplicity, we will format as "<added>+ <modified>~ <deleted>-"
                }

                if p.added>0 {
                    pend_str.push_str(&format!("{}+ ", p.added));
                }
                if p.deleted>0 {
                    pend_str.push_str(&format!("{}- ", p.deleted));
                }
                if p.modified>0 {
                    pend_str.push_str(&format!("{}~ ", p.modified));
                }
                let pend_str = pend_str.trim().to_string();
                if pend_str.is_empty() {
                    continue;
                }
                output.push_str(&format_field("Pending", &pend_str, cli));
            },
            InfoField::VersionInfo(v) => {
                if v.version.is_empty() { continue; }
                output.push_str(&format_field("Version", &v.version, cli));
            },
            InfoField::CreatedInfo(c) => {
                output.push_str(&format_field("Created", &c.creationDate, cli));
            },
            InfoField::LanguagesInfo(l) => {
                if l.languagesWithPercentage.is_empty() { continue; }
                // Format languages
                let langs_str = l.languagesWithPercentage.iter().map(|lp| format!("{} ({:.1} %)", lp.language, lp.percentage)).collect::<Vec<_>>().join(" ");
                output.push_str(&format_field("Language", &langs_str, cli));
            },
            InfoField::DependenciesInfo(d) => {
                if d.dependencies.is_empty() { continue; }
                output.push_str(&format_field("Dependencies", &d.dependencies, cli));
            },
            InfoField::AuthorsInfo(a) => {
                if a.authors.is_empty() { continue; }
                for (i, author) in a.authors.iter().enumerate() {
                    let mut author_str = format!("{}% {} {}", author.contribution, author.name, author.nbrOfCommits);
                    if let Some(ref email) = author.email {
                        author_str = format!("{}% {} <{}> {}", author.contribution, author.name, email, author.nbrOfCommits);
                    }
                    if i==0 {
                        output.push_str(&format_field("Author", &author_str, cli));
                    } else {
                        output.push_str(&format!("{}{}\n", " ".repeat(10), author_str));
                    }
                }
            },
            InfoField::LastChangeInfo(l) => {
                output.push_str(&format_field("Last change", &l.lastChange, cli));
            },
            InfoField::ContributorsInfo(c) => {
                // Only show if total > number of authors displayed?
                if c.totalNumberOfAuthors > cli.number_of_authors {
                    output.push_str(&format_field("Contributors", &c.totalNumberOfAuthors.to_string(), cli));
                } else if c.totalNumberOfAuthors > 1 && cli.number_of_authors >= c.totalNumberOfAuthors {
                    // Actually original shows Contributors only when more than displayed? Let's check: for authTest with 4 authors, number_of_authors default 3, total 4, it showed Contributors: 4. For repo with 2 authors and default 3, it didn't show Contributors? In earlier test with testrepo2 (2 authors), text output didn't show Contributors. So Contributors shown when total > number_of_authors.
                    continue;
                } else {
                    // If only 1 author, not show? In earlier tests, with 1 author, Contributors not shown in text, but present in JSON.
                    continue;
                }
            },
            InfoField::UrlInfo(u) => {
                if u.repoUrl.is_empty() { continue; }
                output.push_str(&format_field("URL", &u.repoUrl, cli));
            },
            InfoField::CommitsInfo(c) => {
                output.push_str(&format_field("Commits", &c.numberOfCommits.to_string(), cli));
            },
            InfoField::ChurnInfo(ch) => {
                // Format: "Churn (pool_size): file1 count"
                let pool = ch.churn_pool_size;
                if ch.file_churns.is_empty() {
                    continue;
                }
                let first = &ch.file_churns[0];
                output.push_str(&format_field(&format!("Churn ({})", pool), &format!("{} {}", first.filePath, first.nbrOfCommits), cli));
                for fc in ch.file_churns.iter().skip(1) {
                    output.push_str(&format!("{}{} {}\n", " ".repeat(12), fc.filePath, fc.nbrOfCommits));
                }
            },
            InfoField::LocInfo(l) => {
                let loc_str = format_number(l.linesOfCode, &cli.number_separator);
                output.push_str(&format_field("Lines of code", &loc_str, cli));
            },
            InfoField::SizeInfo(s) => {
                let size_str = format!("{} ({} files)", s.repoSize, format_number(s.fileCount, &cli.number_separator));
                output.push_str(&format_field("Size", &size_str, cli));
            },
            InfoField::LicenseInfo(l) => {
                if l.license.is_empty() { continue; }
                output.push_str(&format_field("License", &l.license, cli));
            },
        }
    }

    // Ensure ending with \x1b[?7h?
    output.push_str("\x1b[?7h");

    print!("{}", output);
}

fn format_field(title: &str, value: &str, cli: &Cli) -> String {
    let bold = if cli.no_bold { "" } else { ";1" };
    let color = 37; // default white? We'll use 37.
    // Determine color based on title? We use 37 for all for simplicity.
    if !cli.no_bold {
        format!("\x1b[{}{}m{}\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m\n", color, bold, title, value)
    } else {
        format!("\x1b[{}m{}\x1b[0m\x1b[39m:\x1b[0m \x1b[39m{}\x1b[0m\n", color, title, value)
    }
}

fn get_dominant_color(info: &OutputInfo) -> u8 {
    // Try to get dominant language and map to color
    for field in &info.infoFields {
        if let InfoField::LanguagesInfo(l) = field {
            if let Some(first) = l.languagesWithPercentage.first() {
                return match first.language.as_str() {
                    "Rust" => 31,
                    "Python" => 34,
                    "JavaScript" => 33,
                    "Go" => 36,
                    "Java" => 31,
                    "C" => 35,
                    "Cpp" => 34,
                    _ => 37,
                }
            }
        }
    }
    37
}

fn format_number(num: usize, sep: &str) -> String {
    let s = num.to_string();
    match sep {
        "comma" => {
            // add commas every 3 digits
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 {
                    res.push(',');
                }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        "space" => {
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 {
                    res.push(' ');
                }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        "underscore" => {
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 {
                    res.push('_');
                }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        _ => s,
    }
}
