    }

    // Find git repo root by walking up
    let repo_root = find_git_repo_root(path);
    let repo_root = match repo_root {
        Some(r) => r,
        None => {
            eprintln!("Error: Could not find a git repository in '{}' or in any of its parents", input_path);
            std::process::exit(1);
        }
    };

    // Open repo with git2
    let repo = match Repository::open(&repo_root) {
        Ok(r) => r,
        Err(_) => {
            eprintln!("Error: Could not find a git repository in '{}' or in any of its parents", input_path);
            std::process::exit(1);
        }
    };

    // Check for empty repo (no commits)
    let head = repo.head();
    let has_commits = repo.revparse_single("HEAD").is_ok();
    if !has_commits {
        eprintln!("Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch 'refs/heads/master' does not have any commits");
        std::process::exit(1);
    }

    // Gather info
    let info = gather_info(&repo, &repo_root, &cli);

    // Output based on format
    if let Some(ref fmt) = cli.output {
        if fmt == "json" {
            let json = serde_json::to_string_pretty(&info).unwrap();
            println!("{}", json);
        } else if fmt == "yaml" {
            let yaml = serde_yaml::to_string(&info).unwrap();
            println!("{}", yaml);
        }
    } else {
        // Text output
        print_text_output(&info, &cli);
    }
}

fn find_git_repo_root(start: &Path) -> Option<PathBuf> {
    let mut current = start.canonicalize().ok()?;
    loop {
        if current.join(".git").exists() {
            return Some(current);
        }
        if let Some(parent) = current.parent() {
            current = parent.to_path_buf();
        } else {
            break;
        }
    }
    None
}

