fn gather_info(repo: &Repository, repo_root: &Path, cli: &Cli) -> OutputInfo {
    // git version
    let git_version = get_git_version();

    // git username from config
    let git_username = get_git_username(repo);

    // Title
    let title = if cli.no_title {
        None
    } else {
        Some(TitleInfo {
            gitUsername: git_username.clone(),
            gitVersion: git_version,
        })
    };

    // Project
    let (repo_name, number_of_tags) = get_project_info(repo, repo_root);
    let project_info = ProjectInfo {
        repoName: repo_name.clone(),
        numberOfBranches: 0,
        numberOfTags: number_of_tags,
    };

    // Description, Version, License, Dependencies - need to determine dominant package manager
    // For simplicity, we will determine dominant by earliest first appearance as discussed, fallback to filesystem.
    let dominant = determine_dominant_manager(repo, repo_root);

    let description = get_description(repo_root, &dominant);
    let version = get_version(repo, repo_root, &dominant);
    let license = get_license(repo_root, &dominant);
    let dependencies = get_dependencies(repo_root, &dominant);

    // Head
    let head_info = get_head_info(repo);

    // Pending
    let pending = get_pending_info(repo);

    // Created and LastChange
    let (created_date, last_change_date) = get_created_last_change(repo);

    let created_str = if cli.iso_time {
        created_date.to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
    } else {
        format_relative_time(created_date)
    };
    let last_change_str = if cli.iso_time {
        last_change_date.to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
    } else {
        format_relative_time(last_change_date)
    };

    // Languages
    let languages_info = get_languages_info(repo_root, cli);

    // Authors
    let (authors, total_authors, commits_count, is_shallow) = get_authors_info(repo, cli);

    // Url
    let repo_url = get_repo_url(repo, cli);

    // Churn
    let churn_info = get_churn_info(repo, cli);

    // Loc and Size depend on languages file list
    let (loc, size_str, file_count) = get_loc_and_size(repo_root, cli, &languages_info);

    // Build infoFields respecting disabled fields
    let disabled: HashSet<String> = cli.disabled_fields.iter().cloned().collect();

    let mut fields = Vec::new();

    // Order as observed in JSON: Project, Description, Head, Pending, Version, Created, Languages, Dependencies, Authors, LastChange, Contributors, Url, Commits, Churn, Loc, Size, License
    // But note when some fields empty, they may still be present in JSON? In earlier JSON, all fields present even when empty? Let's see for nopackage repo: JSON had all fields including Project, Description null, Head, Pending, Version "", Created, Dependencies "", Authors, LastChange, Contributors, Url "", Commits, Churn, Size, License "" but Languages and Loc missing when no languages. So LanguagesInfo and LocInfo are optional based on whether there is language.
    // Actually for repos with languages, LanguagesInfo present, LocInfo present.
    // For repos without dependencies, DependenciesInfo present with empty string.
    // For all, we should include fields unless disabled, but Languages, Loc may be omitted if empty? Let's check: for txtonly repo, LanguagesInfo missing, Loc missing? Actually txtonly JSON had no LanguagesInfo but also no Loc? It had no Languages, but did it have Loc? The file.txt is plain text, not counted as language, so Loc would be 0? In JSON it had no Loc. So we omit Languages and Loc when no languages.

    if !disabled.contains("project") {
        fields.push(InfoField::ProjectInfo(project_info));
    }
    if !disabled.contains("description") {
        fields.push(InfoField::DescriptionInfo(DescriptionInfo { description }));
    }
    if !disabled.contains("head") {
        fields.push(InfoField::HeadInfo(head_info));
    }
    if !disabled.contains("pending") {
        fields.push(InfoField::PendingInfo(pending));
    }
    if !disabled.contains("version") {
        fields.push(InfoField::VersionInfo(VersionInfo { version }));
    }
    if !disabled.contains("created") {
        fields.push(InfoField::CreatedInfo(CreatedInfo { creationDate: created_str }));
    }
    if !disabled.contains("languages") {
        if let Some(ref lang) = languages_info {
            fields.push(InfoField::LanguagesInfo(lang.clone()));
        }
    }
    if !disabled.contains("dependencies") {
        fields.push(InfoField::DependenciesInfo(DependenciesInfo { dependencies }));
    }
    if !disabled.contains("authors") {
        fields.push(InfoField::AuthorsInfo(AuthorsInfo { authors: authors.clone() }));
    }
    if !disabled.contains("last-change") {
        fields.push(InfoField::LastChangeInfo(LastChangeInfo { lastChange: last_change_str }));
    }
    if !disabled.contains("contributors") {
        fields.push(InfoField::ContributorsInfo(ContributorsInfo { totalNumberOfAuthors: total_authors }));
    }
    if !disabled.contains("url") {
        fields.push(InfoField::UrlInfo(UrlInfo { repoUrl: repo_url }));
    }
    if !disabled.contains("commits") {
        fields.push(InfoField::CommitsInfo(CommitsInfo { numberOfCommits: commits_count, isShallow: is_shallow }));
    }
    if !disabled.contains("churn") {
        fields.push(InfoField::ChurnInfo(churn_info));
    }
    if !disabled.contains("lines-of-code") {
        if languages_info.is_some() {
            fields.push(InfoField::LocInfo(LocInfo { linesOfCode: loc }));
        }
    }
    if !disabled.contains("size") {
        fields.push(InfoField::SizeInfo(SizeInfo { repoSize: size_str, fileCount: file_count }));
    }
    if !disabled.contains("license") {
        fields.push(InfoField::LicenseInfo(LicenseInfo { license }));
    }

    OutputInfo {
        title,
        infoFields: fields,
    }
}

fn get_git_version() -> String {
    match Command::new("git").arg("--version").output() {
        Ok(out) => {
            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
            if s.is_empty() {
                "git version 2.34.1".to_string()
            } else {
                s
            }
        },
        Err(_) => "git version 2.34.1".to_string(),
    }
}

fn get_git_username(repo: &Repository) -> String {
    if let Ok(config) = repo.config() {
        if let Ok(name) = config.get_string("user.name") {
            return name;
        }
    }
    // fallback to global?
    "Dev".to_string()
}

fn get_project_info(repo: &Repository, repo_root: &Path) -> (String, usize) {
    // repo name from remote
    let repo_name = get_repo_name_from_remote(repo);
    // tags count
    let tags = repo.tag_names(None).ok();
    let count = if let Some(t) = tags {
        t.len()
    } else {
        0
    };
    (repo_name, count)
}

fn get_repo_name_from_remote(repo: &Repository) -> String {
    let remote_url = repo.find_remote("origin").ok().and_then(|r| r.url().map(|s| s.to_string()));
    let url_str = match remote_url {
        Some(u) => u,
        None => {
            // try config
            if let Ok(config) = repo.config() {
                if let Ok(u) = config.get_string("remote.origin.url") {
                    u
                } else {
                    return "".to_string();
                }
            } else {
                return "".to_string();
            }
        }
    };
    // parse repo name
    let mut s = url_str.trim().trim_end_matches('/').to_string();
    // for ssh, take after last ':' or '/'
    if let Some(idx) = s.rfind('/') {
        s = s[idx+1..].to_string();
    } else if let Some(idx) = s.rfind(':') {
        s = s[idx+1..].to_string();
    }
    // strip .git suffix once
    if s.ends_with(".git") {
        s = s[..s.len()-4].to_string();
    }
    s
}

#[derive(Clone, Debug, PartialEq)]
enum PackageManager {
    Cargo,
    Npm,
    None,
}

fn determine_dominant_manager(repo: &Repository, repo_root: &Path) -> PackageManager {
    let cargo_path = repo_root.join("Cargo.toml");
    let npm_path = repo_root.join("package.json");
    let cargo_exists = cargo_path.exists();
    let npm_exists = npm_path.exists();

    if cargo_exists && !npm_exists {
        return PackageManager::Cargo;
    }
    if !cargo_exists && npm_exists {
        return PackageManager::Npm;
    }
    if !cargo_exists && !npm_exists {
        return PackageManager::None;
    }
    // both exist, need to check git log for first appearance
    let cargo_first = get_first_commit_time_for_file(repo, "Cargo.toml");
    let npm_first = get_first_commit_time_for_file(repo, "package.json");
    match (cargo_first, npm_first) {
        (Some(c), Some(n)) => {
            if c < n {
                PackageManager::Cargo
            } else if n < c {
                PackageManager::Npm
            } else {
                // tie -> Cargo wins
                PackageManager::Cargo
            }
        },
        (Some(_), None) => PackageManager::Cargo,
        (None, Some(_)) => PackageManager::Npm,
        (None, None) => PackageManager::Cargo, // both appear same commit? default Cargo
    }
}

fn get_first_commit_time_for_file(repo: &Repository, file: &str) -> Option<i64> {
    // Use git command: git log --reverse --format=%ct -- file
    let repo_path = repo.path().parent()?;
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("log")
        .arg("--reverse")
        .arg("--format=%ct")
        .arg("--")
        .arg(file)
        .output()
        .ok()?;
    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in stdout.lines() {
        if let Ok(t) = line.trim().parse::<i64>() {
            return Some(t);
        }
    }
    None
}

fn get_description(repo_root: &Path, dominant: &PackageManager) -> Option<String> {
    // According to earlier, description follows same dominant logic? But we observed description first manifest wins.
    // For simplicity, use dominant manager to pick description, else try both with dominant precedence.
    // Actually for description, if dominant is Cargo, try Cargo first, else Npm first? But we saw when both exist, description first manifest wins which matches dominant.
    // So implement based on dominant.

    match dominant {
        PackageManager::Cargo => {
            if let Some(desc) = read_cargo_description(repo_root) {
                return Some(desc);
            }
            if let Some(desc) = read_npm_description(repo_root) {
                return Some(desc);
            }
            None
        },
        PackageManager::Npm => {
            if let Some(desc) = read_npm_description(repo_root) {
                return Some(desc);
            }
            if let Some(desc) = read_cargo_description(repo_root) {
                return Some(desc);
            }
            None
        },
        PackageManager::None => {
            // try both? Check Cargo first? But earlier we saw Cargo wins tie, but for description we want package wins? Let's follow dominant logic: try Cargo then Npm? Actually for none, try Cargo then Npm?
            if let Some(desc) = read_cargo_description(repo_root) {
                return Some(desc);
            }
            if let Some(desc) = read_npm_description(repo_root) {
                return Some(desc);
            }
            None
        }
    }
}

fn read_cargo_description(repo_root: &Path) -> Option<String> {
    let cargo_path = repo_root.join("Cargo.toml");
    if !cargo_path.exists() {
        return None;
    }
    let content = fs::read_to_string(cargo_path).ok()?;
    // parse toml for [package] description
    // Use toml crate but simple regex
    // Look for description = "..."
    let re = Regex::new(r#"description\s*=\s*"([^"]+)""#).ok()?;
    if let Some(caps) = re.captures(&content) {
        return Some(caps[1].to_string());
    }
    None
}
fn read_npm_description(repo_root: &Path) -> Option<String> {
    let npm_path = repo_root.join("package.json");
    if !npm_path.exists() {
        return None;
    }
    let content = fs::read_to_string(npm_path).ok()?;
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    if let Some(desc) = v.get("description").and_then(|d| d.as_str()) {
        return Some(desc.to_string());
    }
    None
}

fn get_version(repo: &Repository, repo_root: &Path, dominant: &PackageManager) -> String {
    // Check tags first: lexicographically smallest tag
    if let Ok(tags) = repo.tag_names(None) {
        if !tags.is_empty() {
            let mut tag_list: Vec<String> = Vec::new();
            for t in tags.iter() {
                if let Some(s) = t {
                    tag_list.push(s.to_string());
                }
            }
            if !tag_list.is_empty() {
                tag_list.sort();
                return tag_list[0].clone();
            }
        }
    }
    // else Cargo or Npm version based on dominant
    match dominant {
        PackageManager::Cargo => {
            if let Some(v) = read_cargo_version(repo_root) {
                return v;
            }
            if let Some(v) = read_npm_version(repo_root) {
                return v;
            }
            "".to_string()
        },
        PackageManager::Npm => {
            if let Some(v) = read_npm_version(repo_root) {
                return v;
            }
            if let Some(v) = read_cargo_version(repo_root) {
                return v;
            }
            "".to_string()
        },
        PackageManager::None => "".to_string(),
    }
}
fn read_cargo_version(repo_root: &Path) -> Option<String> {
    let cargo_path = repo_root.join("Cargo.toml");
    if !cargo_path.exists() { return None; }
    let content = fs::read_to_string(cargo_path).ok()?;
    let re = Regex::new(r#"version\s*=\s*"([^"]+)""#).ok()?;
    // need to ensure under [package]
    // Simple: find first version in [package] section
    if let Some(idx) = content.find("[package]") {
        let after = &content[idx..];
        if let Some(caps) = re.captures(after) {
            return Some(caps[1].to_string());
        }
    }
    None
}
fn read_npm_version(repo_root: &Path) -> Option<String> {
    let npm_path = repo_root.join("package.json");
    if !npm_path.exists() { return None; }
    let content = fs::read_to_string(npm_path).ok()?;
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    if let Some(ver) = v.get("version").and_then(|d| d.as_str()) {
        return Some(ver.to_string());
    }
    None
}

fn get_license(repo_root: &Path, dominant: &PackageManager) -> String {
    // Only Cargo.toml license or package.json license
    match dominant {
        PackageManager::Cargo => {
            if let Some(l) = read_cargo_license(repo_root) {
                return l;
            }
            if let Some(l) = read_npm_license(repo_root) {
                return l;
            }
            "".to_string()
        },
        PackageManager::Npm => {
            if let Some(l) = read_npm_license(repo_root) {
                return l;
            }
            if let Some(l) = read_cargo_license(repo_root) {
                return l;
            }
            "".to_string()
        },
        PackageManager::None => {
            if let Some(l) = read_cargo_license(repo_root) {
                return l;
            }
            if let Some(l) = read_npm_license(repo_root) {
                return l;
            }
            "".to_string()
        }
    }
}
fn read_cargo_license(repo_root: &Path) -> Option<String> {
    let cargo_path = repo_root.join("Cargo.toml");
    if !cargo_path.exists() { return None; }
    let content = fs::read_to_string(cargo_path).ok()?;
    let re = Regex::new(r#"license\s*=\s*"([^"]+)""#).ok()?;
    if let Some(idx) = content.find("[package]") {
        let after = &content[idx..];
        if let Some(caps) = re.captures(after) {
            return Some(caps[1].to_string());
        }
    }
    None
}
fn read_npm_license(repo_root: &Path) -> Option<String> {
    let npm_path = repo_root.join("package.json");
    if !npm_path.exists() { return None; }
    let content = fs::read_to_string(npm_path).ok()?;
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    if let Some(lic) = v.get("license").and_then(|d| d.as_str()) {
        return Some(lic.to_string());
    }
    None
}

fn get_dependencies(repo_root: &Path, dominant: &PackageManager) -> String {
    match dominant {
        PackageManager::Cargo => {
            if let Some(cnt) = read_cargo_deps(repo_root) {
                return format!("{} (Cargo)", cnt);
            }
            if let Some(cnt) = read_npm_deps(repo_root) {
                return format!("{} (Npm)", cnt);
            }
            "".to_string()
        },
        PackageManager::Npm => {
            if let Some(cnt) = read_npm_deps(repo_root) {
                return format!("{} (Npm)", cnt);
            }
            if let Some(cnt) = read_cargo_deps(repo_root) {
                return format!("{} (Cargo)", cnt);
            }
            "".to_string()
        },
        PackageManager::None => "".to_string(),
    }
}
fn read_cargo_deps(repo_root: &Path) -> Option<usize> {
    let cargo_path = repo_root.join("Cargo.toml");
    if !cargo_path.exists() { return None; }
    let content = fs::read_to_string(cargo_path).ok()?;
    // find [dependencies] section
    let mut count = 0;
    let mut in_deps = false;
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("[dependencies]") {
            in_deps = true;
            continue;
        }
        if trimmed.starts_with("[") {
            if in_deps {
                break;
            }
            in_deps = false;
        }
        if in_deps {
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            if trimmed.contains('=') {
                count += 1;
            }
        }
    }
    if count >0 { Some(count) } else { None }
}
fn read_npm_deps(repo_root: &Path) -> Option<usize> {
    let npm_path = repo_root.join("package.json");
    if !npm_path.exists() { return None; }
    let content = fs::read_to_string(npm_path).ok()?;
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    if let Some(deps) = v.get("dependencies").and_then(|d| d.as_object()) {
        let cnt = deps.len();
        if cnt>0 { return Some(cnt); }
    }
    None
}

fn get_head_info(repo: &Repository) -> HeadInfo {
    let head = repo.head().ok();
    let commit_id = if let Ok(r) = repo.revparse_single("HEAD") {
        let oid = r.id();
        let s = oid.to_string();
        s[..7].to_string()
    } else {
        "0000000".to_string()
    };
    let refs = if let Some(head_ref) = head {
        if head_ref.is_branch() {
            if let Some(name) = head_ref.shorthand() {
                vec![name.to_string()]
            } else {
                vec![]
            }
        } else {
            // detached HEAD
            vec![]
        }
    } else {
        vec![]
    };
    HeadInfo {
        headRefs: HeadRefs {
            shortCommitId: commit_id,
            refs,
        }
    }
}

fn get_pending_info(repo: &Repository) -> PendingInfo {
    let repo_path = repo.path().parent().unwrap();
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("status")
        .arg("--porcelain")
        .output();
    let mut added = 0;
    let mut deleted = 0;
    let mut modified = 0;
    if let Ok(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            if line.starts_with("??") {
                added += 1;
            } else {
                if line.len() >=2 {
                    let chars: Vec<char> = line.chars().collect();
                    let second = chars[1];
                    if second == 'M' {
                        modified +=1;
                    } else if second == 'D' {
                        deleted +=1;
                    }
                }
            }
        }
    }
    PendingInfo { added, deleted, modified }
}

fn get_created_last_change(repo: &Repository) -> (DateTime<Utc>, DateTime<Utc>) {
    // git log --format=%ct reverse
    let repo_path = repo.path().parent().unwrap();
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("log")
        .arg("--reverse")
        .arg("--format=%ct")
        .output();
    let mut timestamps = Vec::new();
    if let Ok(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            if let Ok(ts) = line.trim().parse::<i64>() {
                timestamps.push(ts);
            }
        }
    }
    if timestamps.is_empty() {
        let now = Utc::now();
        return (now, now);
    }
    let first = timestamps[0];
    let last = *timestamps.last().unwrap();
    let created = Utc.timestamp_opt(first, 0).unwrap();
    let last_change = Utc.timestamp_opt(last, 0).unwrap();
    (created, last_change)
}

fn format_relative_time(dt: DateTime<Utc>) -> String {
    let now = Utc::now();
    let duration = now.signed_duration_since(dt);
    let secs = duration.num_seconds();
    if secs < 0 {
        return "now".to_string();
    }
    if secs < 45 {
        return "now".to_string();
    }
    if secs < 90 {
        return "a minute ago".to_string();
    }
    if secs < 45*60 {
        let mins = secs / 60;
        return format!("{} minutes ago", mins);
    }
    if secs < 90*60 {
        return "an hour ago".to_string();
    }
    if secs < 22*3600 {
        let hours = secs / 3600;
        return format!("{} hours ago", hours);
    }
    if secs < 36*3600 {
        return "a day ago".to_string();
    }
    if secs < 6*24*3600 {
        let days = secs / (24*3600);
        return format!("{} days ago", days);
    }
    if secs < 11*24*3600 {
        return "a week ago".to_string();
    }
    if secs < 25*24*3600 {
        let weeks = secs / (7*24*3600);
        return format!("{} weeks ago", weeks);
    }
    if secs < 45*24*3600 {
        return "a month ago".to_string();
    }
    if secs < 345*24*3600 {
        let months = secs / (30*24*3600);
        if months <=1 {
            return "a month ago".to_string();
        } else {
            return format!("{} months ago", months);
        }
    }
    if secs < 545*24*3600 {
        return "a year ago".to_string();
    }
    let years = secs / (365*24*3600);
    if years <=1 {
        "a year ago".to_string()
    } else {
        format!("{} years ago", years)
    }
}

fn get_languages_info(repo_root: &Path, cli: &Cli) -> Option<LanguagesInfo> {
    // Walk files, respecting exclude and include_hidden
    let files = collect_files(repo_root, cli);
    // Map extension to language
    let mut lang_bytes: HashMap<String, usize> = HashMap::new();
    // Also need loc per file for percentage based on loc? Or based on file count? In earlier test, percentage was based on ??? For repo with a.py 2 lines and b.js 1 line, percentages 66.6 and 33.3 based on lines? Yes Python 2 lines vs JS 1 line => 66.6 vs 33.3. So percentage based on loc.

    // For each file, detect language, count loc (simple non-empty lines), accumulate bytes? Actually loc for percentage.
    let mut lang_loc: HashMap<String, usize> = HashMap::new();

    for file_path in files {
        if let Some(lang) = detect_language(&file_path) {
            // Check type filter
            let lang_type = get_language_type(&lang);
            if !cli.type_filter.contains(&lang_type) {
                continue;
            }
            // Count loc
            if let Ok(content) = fs::read_to_string(&file_path) {
                let loc = content.lines().filter(|l| !l.trim().is_empty()).count();
                // For simplicity, count all non-empty as loc
                *lang_loc.entry(lang.clone()).or_insert(0) += loc;
            }
        }
    }

    if lang_loc.is_empty() {
        return None;
    }

    let total_loc: usize = lang_loc.values().sum();
    let mut percentages: Vec<LanguagePercentage> = Vec::new();
    for (lang, loc) in lang_loc {
        let perc = if total_loc >0 {
            (loc as f64 / total_loc as f64) * 100.0
        } else { 0.0 };
        percentages.push(LanguagePercentage { language: lang, percentage: perc });
    }
    // Sort by percentage descending
    percentages.sort_by(|a,b| b.percentage.partial_cmp(&a.percentage).unwrap());
    // Limit by number_of_languages
    let limited = percentages.into_iter().take(cli.number_of_languages).collect();
    Some(LanguagesInfo { languagesWithPercentage: limited })
}

fn collect_files(repo_root: &Path, cli: &Cli) -> Vec<PathBuf> {
    let mut files = Vec::new();
    // Use git ls-files to get tracked files
    let repo_path = repo_root;
    let output = Command::new("git")
        .arg("-C")
        .arg(repo_path)
        .arg("ls-files")
        .output();
    if let Ok(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let file_path = repo_path.join(line);
            if !file_path.exists() { continue; }
            // Check hidden
            if !cli.include_hidden {
                // if any component starts with '.' => skip
                let mut is_hidden = false;
                for comp in file_path.components() {
                    if let Some(s) = comp.as_os_str().to_str() {
                        if s.starts_with('.') && s != "." && s != ".." {
                            is_hidden = true;
                            break;
                        }
                    }
                }
                if is_hidden { continue; }
            }
            // Check exclude patterns (simple glob)
            let mut excluded = false;
            for pattern in &cli.exclude {
                // Use glob matching
                // pattern may be like "*.rs" or "src/*"
                // We'll use glob crate matching against relative path
                let rel = file_path.strip_prefix(repo_path).unwrap_or(&file_path);
                let rel_str = rel.to_string_lossy();
                // simple matching: if pattern contains *, use glob, else substring
                if pattern.contains('*') {
                    if glob::Pattern::new(pattern).map(|p| p.matches(&rel_str) || p.matches(file_path.file_name().unwrap_or_default().to_string_lossy().as_ref())).unwrap_or(false) {
                        excluded = true;
                        break;
                    }
                } else {
                    if rel_str.contains(pattern) {
                        excluded = true;
                        break;
                    }
                }
            }
            if excluded { continue; }
            files.push(file_path);
        }
    } else {
        // fallback walkdir
        for entry in walkdir::WalkDir::new(repo_path).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                let p = entry.path();
                if p.to_string_lossy().contains(".git") { continue; }
                files.push(p.to_path_buf());
            }
        }
    }
    files
}

