fn get_authors_info(repo: &Repository, cli: &Cli) -> (Vec<Author>, usize, usize, bool) {
    // git log --format="%an %ae"
    let repo_path = repo.path().parent().unwrap();
    let mut cmd = Command::new("git");
    cmd.arg("-C").arg(repo_path).arg("log").arg("--format=%an%x01%ae%x01%H%x01%P");
    if cli.no_merges {
        cmd.arg("--no-merges");
    }
    let output = cmd.output().ok();
    let mut commits: Vec<(String, String, String, String)> = Vec::new(); // name, email, hash, parents
    if let Some(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let parts: Vec<&str> = line.split('\x01').collect();
            if parts.len() >=4 {
                commits.push((parts[0].to_string(), parts[1].to_string(), parts[2].to_string(), parts[3].to_string()));
            }
        }
    }

    // Bot filtering
    let bot_regex: Option<Regex> = if let Some(ref pattern) = cli.no_bots {
        if pattern.is_empty() {
            Some(Regex::new(r"\[bot\]").unwrap())
        } else {
            Regex::new(pattern).ok()
        }
    } else {
        None
    };

    let mut filtered_commits: Vec<(String,String)> = Vec::new();
    for (name, email, _hash, _parents) in &commits {
        if let Some(ref re) = bot_regex {
            if re.is_match(name) {
                continue;
            }
        }
        filtered_commits.push((name.clone(), email.clone()));
    }

    let total_commits = filtered_commits.len();

    // Count per author name
    let mut count_map: HashMap<String, (usize, String)> = HashMap::new(); // name -> (count, email)
    for (name, email) in filtered_commits {
        let entry = count_map.entry(name.clone()).or_insert((0, email.clone()));
        entry.0 +=1;
        // keep first email
    }

    let mut authors_vec: Vec<(String, usize, String)> = Vec::new();
    for (name, (cnt, email)) in count_map {
        authors_vec.push((name, cnt, email));
    }
    // Sort by count descending
    authors_vec.sort_by(|a,b| b.1.cmp(&a.1));

    let total_authors = authors_vec.len();

    let limited = authors_vec.into_iter().take(cli.number_of_authors).collect::<Vec<_>>();

    let mut authors_info = Vec::new();
    for (name, cnt, email) in limited {
        let contribution = if total_commits>0 {
            ((cnt as f64 / total_commits as f64) * 100.0).round() as usize
        } else { 0 };
        authors_info.push(Author {
            name,
            email: if cli.email { Some(email) } else { None },
            nbrOfCommits: cnt,
            contribution,
        });
    }

    // commits count and shallow?
    let is_shallow = repo.is_shallow();

    (authors_info, total_authors, total_commits, is_shallow)
}

fn get_repo_url(repo: &Repository, cli: &Cli) -> String {
    let mut url = {
        let remote_url = repo.find_remote("origin").ok().and_then(|r| r.url().map(|s| s.to_string()));
        if let Some(u) = remote_url {
            u
        } else if let Ok(config) = repo.config() {
            config.get_string("remote.origin.url").unwrap_or_else(|_| "".to_string())
        } else {
            "".to_string()
        }
    };

    if url.is_empty() {
        return "".to_string();
    }

    // hide token
    if cli.hide_token {
        // If URL contains token like https://token@github.com/...
        // Remove token part: https://<token>@...
        // Parse url
        if let Ok(mut parsed) = url::Url::parse(&url) {
            if parsed.username() != "" {
                // Remove password? Actually token is username? In https://token@github.com, username is token
                // Hide token: replace username with empty? Original behavior: hide token in repository URL -> shows https://github.com/... without token
                // So set username empty and password None
                let _ = parsed.set_username("");
                let _ = parsed.set_password(None);
                url = parsed.to_string();
                // Remove trailing slash? Keep as is
                if url.ends_with('/') {
                    // keep?
                }
            }
        } else {
            // fallback regex for https://token@...
            if let Some(at_pos) = url.find('@') {
                if let Some(slash_pos) = url[..at_pos].rfind('/') {
                    // Actually pattern https://token@...
                    if url[..at_pos].contains("://") {
                        let before = &url[..url.find("://").unwrap()+3];
                        let after = &url[at_pos+1..];
                        url = format!("{}{}", before, after);
                    }
                }
            }
        }
    }

    // http-url conversion
    if cli.http_url {
        // Convert git@github.com:user/repo.git to https://github.com/user/repo.git
        if url.starts_with("git@") {
            // git@github.com:user/repo.git
            if let Some(colon) = url.find(':') {
                let host = &url[4..colon];
                let path = &url[colon+1..];
                url = format!("https://{}/{}", host, path);
            }
        } else if url.starts_with("ssh://") {
            // ssh://git@github.com/user/repo.git
            if let Ok(parsed) = url::Url::parse(&url) {
                let host = parsed.host_str().unwrap_or("");
                let path = parsed.path().trim_start_matches('/');
                url = format!("https://{}/{}", host, path);
            }
        }
        // If url is already https, keep.
    }

    url
}

fn get_churn_info(repo: &Repository, cli: &Cli) -> ChurnInfo {
    let repo_path = repo.path().parent().unwrap();
    let pool_size = if let Some(n) = cli.churn_pool_size {
        n
    } else {
        // default 1 for simplicity
        1
    };

    // Get commits from HEAD, up to pool_size
    let mut cmd = Command::new("git");
    cmd.arg("-C").arg(repo_path).arg("log").arg(format!("-n{}", pool_size)).arg("--format=%H").arg("--name-only").arg("--pretty=format:");
    if cli.no_merges {
        cmd.arg("--no-merges");
    }
    let output = cmd.output().ok();
    let mut file_counts: HashMap<String, usize> = HashMap::new();
    if let Some(out) = output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() { continue; }
            // Apply exclude and hidden filtering? For churn, should respect exclude?
            // We should check if file matches exclude patterns and skip.
            let mut excluded = false;
            for pattern in &cli.exclude {
                if pattern.contains('*') {
                    if glob::Pattern::new(pattern).map(|p| p.matches(trimmed)).unwrap_or(false) {
                        excluded = true;
                        break;
                    }
                } else {
                    if trimmed.contains(pattern) {
                        excluded = true;
                        break;
                    }
                }
            }
            if excluded { continue; }
            if !cli.include_hidden {
                if trimmed.split('/').any(|comp| comp.starts_with('.') && comp != "." && comp != "..") {
                    continue;
                }
            }
            *file_counts.entry(trimmed.to_string()).or_insert(0) +=1;
        }
    }

    let mut churns: Vec<FileChurn> = file_counts.into_iter().map(|(path, cnt)| FileChurn { filePath: path, nbrOfCommits: cnt }).collect();
    // Sort by nbrOfCommits descending, then by filePath?
    churns.sort_by(|a,b| {
        b.nbrOfCommits.cmp(&a.nbrOfCommits).then(a.filePath.cmp(&b.filePath))
    });

    let limited = churns.into_iter().take(cli.number_of_file_churns).collect();

    ChurnInfo {
        file_churns: limited,
        churn_pool_size: pool_size,
