fn get_loc_and_size(repo_root: &Path, cli: &Cli, languages_info: &Option<LanguagesInfo>) -> (usize, String, usize) {
    let files = collect_files(repo_root, cli);
    let mut total_loc = 0;
    let mut total_size: u64 = 0;
    let mut file_count = 0;

    for file_path in &files {
        // Only count files that are detected as language and pass type filter
        if let Some(lang) = detect_language(file_path) {
            let lang_type = get_language_type(&lang);
            if !cli.type_filter.contains(&lang_type) {
                continue;
            }
            // For loc, count non-empty lines
            if let Ok(content) = fs::read_to_string(file_path) {
                let loc = content.lines().filter(|l| !l.trim().is_empty()).count();
                total_loc += loc;
            }
            if let Ok(metadata) = fs::metadata(file_path) {
                total_size += metadata.len();
            }
            file_count +=1;
        } else {
            // If file has no language, does it contribute to size? In earlier tests, file.txt with no language still contributed to size? Let's check: for txtonly repo, size was 6 B (1 file) even though LanguagesInfo missing. So file without language still counts for size? Actually txtonly had file.txt 6 B counted. So size should count all tracked files, not just those with language.
            // So we should count all files for size, but only language files for loc.
            // For simplicity, we will count all files for size.
            if let Ok(metadata) = fs::metadata(file_path) {
                total_size += metadata.len();
                file_count +=1;
            }
        }
    }

    // If we counted size only for language files, file.txt would not be counted, but we saw txtonly counted. So above we count all.
    // However our files list already includes only tracked files, but we filtered hidden and exclude, which matches size.
    // For loc, only language files.

    let size_str = format_size(total_size);

    (total_loc, size_str, file_count)
}

fn format_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024*1024 {
        let kib = bytes as f64 / 1024.0;
        format!("{:.2} KiB", kib)
    } else if bytes < 1024*1024*1024 {
        let mib = bytes as f64 / (1024.0*1024.0);
        format!("{:.2} MiB", mib)
    } else {
        let gib = bytes as f64 / (1024.0*1024.0*1024.0);
        format!("{:.2} GiB", gib)
    }
}

