fn format_field(title: &str, value: &str, cli: &Cli) -> String {
    let bold = if cli.no_bold { "" } else { ";1" };
    let color = 37; // default white? We'll use 37.
    // Determine color based on title? We use 37 for all for simplicity.
    if !cli.no_bold {
        format!("\x1b[{}{}m{}\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m\n", color, bold, title, value)
    } else {
