fn get_dominant_color(info: &OutputInfo) -> u8 {
    // Try to get dominant language and map to color
    for field in &info.infoFields {
        if let InfoField::LanguagesInfo(l) = field {
            if let Some(first) = l.languagesWithPercentage.first() {
                return match first.language.as_str() {
                    "Rust" => 31,
                    "Python" => 34,
                    "JavaScript" => 33,
                    "Go" => 36,
                    "Java" => 31,
                    "C" => 35,
                    "Cpp" => 34,
                    _ => 37,
                }
            }
        }
    }
    37
}

fn format_number(num: usize, sep: &str) -> String {
    let s = num.to_string();
    match sep {
        "comma" => {
            // add commas every 3 digits
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 {
                    res.push(',');
                }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        "space" => {
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 {
                    res.push(' ');
                }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        "underscore" => {
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 {
                    res.push('_');
                }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        _ => s,
    }
}
