    gitUsername: String,
    gitVersion: String,
}
#[derive(Serialize, Debug)]
enum InfoField {
    ProjectInfo(ProjectInfo),
    DescriptionInfo(DescriptionInfo),
    HeadInfo(HeadInfo),
    PendingInfo(PendingInfo),
    VersionInfo(VersionInfo),
    CreatedInfo(CreatedInfo),
    LanguagesInfo(LanguagesInfo),
    DependenciesInfo(DependenciesInfo),
    AuthorsInfo(AuthorsInfo),
    LastChangeInfo(LastChangeInfo),
    ContributorsInfo(ContributorsInfo),
    UrlInfo(UrlInfo),
    CommitsInfo(CommitsInfo),
    ChurnInfo(ChurnInfo),
    LocInfo(LocInfo),
    SizeInfo(SizeInfo),
    LicenseInfo(LicenseInfo),
}
#[derive(Serialize, Debug)]
struct ProjectInfo {
    repoName: String,
    numberOfBranches: usize,
    numberOfTags: usize,
}
#[derive(Serialize, Debug)]
struct DescriptionInfo {
    description: Option<String>,
}
#[derive(Serialize, Debug)]
struct HeadInfo {
    headRefs: HeadRefs,
}
#[derive(Serialize, Debug)]
struct HeadRefs {
    shortCommitId: String,
    refs: Vec<String>,
}
#[derive(Serialize, Debug)]
struct PendingInfo {
    added: usize,
    deleted: usize,
    modified: usize,
}
#[derive(Serialize, Debug)]
struct VersionInfo {
    version: String,
}
#[derive(Serialize, Debug)]
struct CreatedInfo {
    creationDate: String,
}
#[derive(Serialize, Debug, Clone)]
struct LanguagesInfo {
