#[derive(Debug, Clone)]
struct ParsedCli {
    disabled_fields: Vec<String>,
    no_title: bool,
    number_of_authors: usize,
    number_of_languages: usize,
    number_of_file_churns: usize,
    churn_pool_size: Option<usize>,
    exclude: Vec<String>,
    no_bots: Option<String>,
    no_merges: bool,
    email: bool,
    http_url: bool,
    hide_token: bool,
    include_hidden: bool,
    type_filter: Vec<String>,
    iso_time: bool,
    number_separator: String,
    no_bold: bool,
    output: Option<String>,
}

impl ParsedCli {
    fn from_matches(m: &clap::ArgMatches) -> Self {
        Self {
            disabled_fields: m.get_many::<String>("disabled-fields").map(|v| v.cloned().collect()).unwrap_or_default(),
            no_title: m.get_flag("no-title"),
            number_of_authors: m.get_one::<String>("number-of-authors").and_then(|s| s.parse().ok()).unwrap_or(3),
            number_of_languages: m.get_one::<String>("number-of-languages").and_then(|s| s.parse().ok()).unwrap_or(6),
            number_of_file_churns: m.get_one::<String>("number-of-file-churns").and_then(|s| s.parse().ok()).unwrap_or(3),
            churn_pool_size: m.get_one::<String>("churn-pool-size").and_then(|s| s.parse().ok()),
            exclude: m.get_many::<String>("exclude").map(|v| v.cloned().collect()).unwrap_or_default(),
            no_bots: m.get_one::<String>("no-bots").cloned(),
            no_merges: m.get_flag("no-merges"),
            email: m.get_flag("email"),
            http_url: m.get_flag("http-url"),
            hide_token: m.get_flag("hide-token"),
            include_hidden: m.get_flag("include-hidden"),
            type_filter: m.get_many::<String>("type").map(|v| v.cloned().collect()).unwrap_or_else(|| vec!["programming".to_string(),"markup".to_string()]),
            iso_time: m.get_flag("iso-time"),
            number_separator: m.get_one::<String>("number-separator").cloned().unwrap_or_else(|| "plain".to_string()),
            no_bold: m.get_flag("no-bold"),
            output: m.get_one::<String>("output").cloned(),
        }
    }
}

fn find_git_repo_root(start: &Path) -> Option<PathBuf> {
    let mut current = start.canonicalize().ok()?;
    loop {
        if current.join(".git").exists() {
            return Some(current);
        }
        if let Some(parent) = current.parent() {
            current = parent.to_path_buf();
        } else {
            break;
        }
    }
    None
}

