fn gather_info(repo: &Repository, repo_root: &Path, cli: &ParsedCli) -> OutputInfo {
    let git_version = get_git_version();
    let git_username = get_git_username(repo);
    let title = if cli.no_title {
        None
    } else {
        Some(TitleInfo { gitUsername: git_username, gitVersion: git_version })
    };

    let (repo_name, number_of_tags) = get_project_info(repo);
    let project_info = ProjectInfo { repoName: repo_name, numberOfBranches: 0, numberOfTags: number_of_tags };

    let dominant = determine_dominant_manager(repo, repo_root);

    let description = get_description(repo_root, &dominant);
    let version = get_version(repo, repo_root, &dominant);
    let license = get_license(repo_root, &dominant);
    let dependencies = get_dependencies(repo_root, &dominant);

    let head_info = get_head_info(repo);
    let pending = get_pending_info(repo);
    let (created_date, last_change_date) = get_created_last_change(repo);

    let created_str = if cli.iso_time {
        created_date.to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
    } else {
        format_relative_time(created_date)
    };
    let last_change_str = if cli.iso_time {
        last_change_date.to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
    } else {
        format_relative_time(last_change_date)
    };

    let languages_info = get_languages_info(repo_root, cli);
    let (authors, total_authors, commits_count, is_shallow) = get_authors_info(repo, cli);
    let repo_url = get_repo_url(repo, cli);
    let churn_info = get_churn_info(repo, cli);
    let (loc, size_str, file_count) = get_loc_and_size(repo_root, cli);

    let disabled: HashSet<String> = cli.disabled_fields.iter().cloned().collect();
    let mut fields = Vec::new();

    if !disabled.contains("project") { fields.push(InfoField::ProjectInfo(project_info)); }
    if !disabled.contains("description") { fields.push(InfoField::DescriptionInfo(DescriptionInfo { description })); }
    if !disabled.contains("head") { fields.push(InfoField::HeadInfo(head_info)); }
    if !disabled.contains("pending") { fields.push(InfoField::PendingInfo(pending)); }
    if !disabled.contains("version") { fields.push(InfoField::VersionInfo(VersionInfo { version })); }
    if !disabled.contains("created") { fields.push(InfoField::CreatedInfo(CreatedInfo { creationDate: created_str })); }
    if !disabled.contains("languages") {
        if let Some(ref lang) = languages_info { fields.push(InfoField::LanguagesInfo(lang.clone())); }
    }
    if !disabled.contains("dependencies") { fields.push(InfoField::DependenciesInfo(DependenciesInfo { dependencies })); }
    if !disabled.contains("authors") { fields.push(InfoField::AuthorsInfo(AuthorsInfo { authors: authors.clone() })); }
    if !disabled.contains("last-change") { fields.push(InfoField::LastChangeInfo(LastChangeInfo { lastChange: last_change_str })); }
    if !disabled.contains("contributors") { fields.push(InfoField::ContributorsInfo(ContributorsInfo { totalNumberOfAuthors: total_authors })); }
    if !disabled.contains("url") { fields.push(InfoField::UrlInfo(UrlInfo { repoUrl: repo_url })); }
    if !disabled.contains("commits") { fields.push(InfoField::CommitsInfo(CommitsInfo { numberOfCommits: commits_count, isShallow: is_shallow })); }
    if !disabled.contains("churn") { fields.push(InfoField::ChurnInfo(churn_info)); }
    if !disabled.contains("lines-of-code") {
        if languages_info.is_some() { fields.push(InfoField::LocInfo(LocInfo { linesOfCode: loc })); }
    }
    if !disabled.contains("size") { fields.push(InfoField::SizeInfo(SizeInfo { repoSize: size_str, fileCount: file_count })); }
    if !disabled.contains("license") { fields.push(InfoField::LicenseInfo(LicenseInfo { license })); }

    OutputInfo { title, infoFields: fields }
}

fn get_git_version() -> String {
    match ProcessCommand::new("git").arg("--version").output() {
        Ok(out) => {
            let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
            if s.is_empty() { "git version 2.34.1".to_string() } else { s }
        },
        Err(_) => "git version 2.34.1".to_string(),
    }
}
fn get_git_username(repo: &Repository) -> String {
    if let Ok(config) = repo.config() {
        if let Ok(name) = config.get_string("user.name") { return name; }
    }
    "Dev".to_string()
}
fn get_project_info(repo: &Repository) -> (String, usize) {
    let repo_name = get_repo_name_from_remote(repo);
    let count = repo.tag_names(None).map(|t| t.len()).unwrap_or(0);
    (repo_name, count)
}
fn get_repo_name_from_remote(repo: &Repository) -> String {
    let url_str = repo.find_remote("origin").ok().and_then(|r| r.url().map(|s| s.to_string()).ok()).unwrap_or_else(|| {
        repo.config().ok().and_then(|c| c.get_string("remote.origin.url").ok()).unwrap_or_default()
    });
    if url_str.is_empty() { return "".to_string(); }
    let mut s = url_str.trim().trim_end_matches('/').to_string();
    if let Some(idx) = s.rfind('/') { s = s[idx+1..].to_string(); }
    else if let Some(idx) = s.rfind(':') { s = s[idx+1..].to_string(); }
    if s.ends_with(".git") { s = s[..s.len()-4].to_string(); }
    s
}

#[derive(Clone, Debug, PartialEq)]
enum PackageManager { Cargo, Npm, None }

fn determine_dominant_manager(repo: &Repository, repo_root: &Path) -> PackageManager {
    let cargo_exists = repo_root.join("Cargo.toml").exists();
    let npm_exists = repo_root.join("package.json").exists();
    if cargo_exists && !npm_exists { return PackageManager::Cargo; }
    if !cargo_exists && npm_exists { return PackageManager::Npm; }
    if !cargo_exists && !npm_exists { return PackageManager::None; }
    let cargo_first = get_first_commit_time_for_file(repo, "Cargo.toml");
    let npm_first = get_first_commit_time_for_file(repo, "package.json");
    match (cargo_first, npm_first) {
        (Some(c), Some(n)) => {
            if c < n { PackageManager::Cargo } else if n < c { PackageManager::Npm } else { PackageManager::Cargo }
        },
        (Some(_), None) => PackageManager::Cargo,
        (None, Some(_)) => PackageManager::Npm,
        (None, None) => PackageManager::Cargo,
    }
}
fn get_first_commit_time_for_file(repo: &Repository, file: &str) -> Option<i64> {
    let repo_path = repo.path().parent()?;
    let output = ProcessCommand::new("git").arg("-C").arg(repo_path).arg("log").arg("--reverse").arg("--format=%ct").arg("--").arg(file).output().ok()?;
    let stdout = String::from_utf8_lossy(&output.stdout);
    for line in stdout.lines() {
        if let Ok(t) = line.trim().parse::<i64>() { return Some(t); }
    }
    None
}

fn get_description(repo_root: &Path, dominant: &PackageManager) -> Option<String> {
    match dominant {
        PackageManager::Cargo => {
            if let Some(desc) = read_cargo_description(repo_root) { return Some(desc); }
            read_npm_description(repo_root)
        },
        PackageManager::Npm => {
            if let Some(desc) = read_npm_description(repo_root) { return Some(desc); }
            read_cargo_description(repo_root)
        },
        PackageManager::None => {
            if let Some(desc) = read_cargo_description(repo_root) { return Some(desc); }
            read_npm_description(repo_root)
        }
    }
}
fn read_cargo_description(repo_root: &Path) -> Option<String> {
    let content = fs::read_to_string(repo_root.join("Cargo.toml")).ok()?;
    let re = Regex::new(r#"description\s*=\s*"([^"]+)""#).ok()?;
    re.captures(&content).map(|c| c[1].to_string())
}
fn read_npm_description(repo_root: &Path) -> Option<String> {
    let content = fs::read_to_string(repo_root.join("package.json")).ok()?;
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    v.get("description").and_then(|d| d.as_str()).map(|s| s.to_string())
}
fn get_version(repo: &Repository, repo_root: &Path, dominant: &PackageManager) -> String {
    if let Ok(tags) = repo.tag_names(None) {
        if tags.len()>0 {
            let mut list = Vec::new();
            for t in tags.iter() {
                if let Ok(Some(s)) = t { list.push(s.to_string()); }
            }
            if !list.is_empty() {
                list.sort();
                return list[0].clone();
            }
        }
    }
    match dominant {
        PackageManager::Cargo => {
            if let Some(v) = read_cargo_version(repo_root) { return v; }
            if let Some(v) = read_npm_version(repo_root) { return v; }
            "".to_string()
        },
        PackageManager::Npm => {
            if let Some(v) = read_npm_version(repo_root) { return v; }
            if let Some(v) = read_cargo_version(repo_root) { return v; }
            "".to_string()
        },
        PackageManager::None => "".to_string(),
    }
}
fn read_cargo_version(repo_root: &Path) -> Option<String> {
    let content = fs::read_to_string(repo_root.join("Cargo.toml")).ok()?;
    let re = Regex::new(r#"version\s*=\s*"([^"]+)""#).ok()?;
    if let Some(idx) = content.find("[package]") {
        let after = &content[idx..];
        if let Some(caps) = re.captures(after) { return Some(caps[1].to_string()); }
    }
    None
}
fn read_npm_version(repo_root: &Path) -> Option<String> {
