        Some(r) => r,
        None => {
            eprintln!("Error: Could not find a git repository in '{}' or in any of its parents", input_path_str);
            std::process::exit(1);
        }
    };

    let repo = match Repository::open(&repo_root) {
        Ok(r) => r,
        Err(_) => {
            eprintln!("Error: Could not find a git repository in '{}' or in any of its parents", input_path_str);
            std::process::exit(1);
        }
    };

    if repo.revparse_single("HEAD").is_err() {
        eprintln!("Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch 'refs/heads/master' does not have any commits");
        std::process::exit(1);
    }

    let cli_parsed = ParsedCli::from_matches(&matches);

    let info = gather_info(&repo, &repo_root, &cli_parsed);

    if let Some(fmt) = cli_parsed.output {
        if fmt == "json" {
            let json = serde_json::to_string_pretty(&info).unwrap();
            println!("{}", json);
        } else if fmt == "yaml" {
            let yaml = serde_yaml::to_string(&info).unwrap();
            println!("{}", yaml);
