fn format_number(num: usize, sep: &str) -> String {
    let s = num.to_string();
    match sep {
        "comma" => {
            let mut res=String::new(); let mut count=0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 { res.push(','); }
                res.push(c); count+=1;
            }
            res.chars().rev().collect()
        },
        "space" => {
            let mut res=String::new(); let mut count=0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 { res.push(' '); }
                res.push(c); count+=1;
            }
            res.chars().rev().collect()
        },
        "underscore" => {
            let mut res=String::new(); let mut count=0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 { res.push('_'); }
                res.push(c); count+=1;
            }
            res.chars().rev().collect()
        },
        _=>s,
    }
}
