fn get_authors_info(repo: &Repository, cli: &ParsedCli) -> (Vec<Author>, usize, usize, bool) {
    let repo_path = repo.path().parent().unwrap();
    let mut cmd = ProcessCommand::new("git");
    cmd.arg("-C").arg(repo_path).arg("log").arg("--format=%an%x01%ae%x01%H%x01%P");
    if cli.no_merges { cmd.arg("--no-merges"); }
    let output = cmd.output().ok();
    let mut commits: Vec<(String,String,String,String)> = Vec::new();
    if let Some(out)=output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let parts: Vec<&str> = line.split('\x01').collect();
            if parts.len()>=4 { commits.push((parts[0].to_string(), parts[1].to_string(), parts[2].to_string(), parts[3].to_string())); }
        }
    }
    let bot_regex: Option<Regex> = if let Some(ref pattern) = cli.no_bots {
        if pattern.is_empty() { Some(Regex::new(r"\[bot\]").unwrap()) } else { Regex::new(pattern).ok() }
    } else { None };
    let mut filtered: Vec<(String,String)> = Vec::new();
    for (name,email,_,_) in &commits {
        if let Some(ref re)=bot_regex {
            if re.is_match(name) { continue; }
        }
        filtered.push((name.clone(), email.clone()));
    }
    let total_commits = filtered.len();
    let mut count_map: HashMap<String,(usize,String)> = HashMap::new();
    for (name,email) in filtered {
        let entry = count_map.entry(name.clone()).or_insert((0,email.clone()));
        entry.0+=1;
    }
    let mut vec: Vec<(String,usize,String)> = Vec::new();
    for (name,(cnt,email)) in count_map { vec.push((name,cnt,email)); }
    vec.sort_by(|a,b| b.1.cmp(&a.1));
    let total_authors = vec.len();
    let limited = vec.into_iter().take(cli.number_of_authors).collect::<Vec<_>>();
    let mut authors_info = Vec::new();
    for (name,cnt,email) in limited {
        let contribution = if total_commits>0 { ((cnt as f64 / total_commits as f64)*100.0).round() as usize } else {0};
        authors_info.push(Author { name, email: if cli.email { Some(email) } else { None }, nbrOfCommits: cnt, contribution });
    }
    let is_shallow = repo.is_shallow();
    (authors_info, total_authors, total_commits, is_shallow)
}
fn get_repo_url(repo: &Repository, cli: &ParsedCli) -> String {
    let mut url = repo.find_remote("origin").ok().and_then(|r| r.url().map(|s| s.to_string()).ok()).unwrap_or_else(|| {
        repo.config().ok().and_then(|c| c.get_string("remote.origin.url").ok()).unwrap_or_default()
    });
    if url.is_empty() { return "".to_string(); }
    if cli.hide_token {
        if let Ok(mut parsed)=url::Url::parse(&url) {
            if parsed.username()!="" {
                let _=parsed.set_username("");
                let _=parsed.set_password(None);
                url = parsed.to_string();
            }
        } else {
            if let Some(at_pos)=url.find('@') {
                if url[..at_pos].contains("://") {
                    let before = &url[..url.find("://").unwrap()+3];
                    let after = &url[at_pos+1..];
                    url = format!("{}{}", before, after);
                }
            }
        }
    }
    if cli.http_url {
        if url.starts_with("git@") {
            if let Some(colon)=url.find(':') {
                let host = &url[4..colon];
                let path = &url[colon+1..];
                url = format!("https://{}/{}", host, path);
            }
        } else if url.starts_with("ssh://") {
            if let Ok(parsed)=url::Url::parse(&url) {
                let host = parsed.host_str().unwrap_or("");
                let path = parsed.path().trim_start_matches('/');
                url = format!("https://{}/{}", host, path);
            }
        }
    }
    url
}
fn get_churn_info(repo: &Repository, cli: &ParsedCli) -> ChurnInfo {
    let repo_path = repo.path().parent().unwrap();
    let pool_size = cli.churn_pool_size.unwrap_or(1);
    let mut cmd = ProcessCommand::new("git");
    cmd.arg("-C").arg(repo_path).arg("log").arg(format!("-n{}", pool_size)).arg("--format=%H").arg("--name-only").arg("--pretty=format:");
    if cli.no_merges { cmd.arg("--no-merges"); }
    let output = cmd.output().ok();
    let mut file_counts: HashMap<String, usize> = HashMap::new();
    if let Some(out)=output {
        let stdout = String::from_utf8_lossy(&out.stdout);
        for line in stdout.lines() {
            let trimmed = line.trim();
            if trimmed.is_empty() { continue; }
            let mut excluded=false;
            for pattern in &cli.exclude {
                if pattern.contains('*') {
                    if glob::Pattern::new(pattern).map(|p| p.matches(trimmed)).unwrap_or(false) { excluded=true; break; }
                } else {
                    if trimmed.contains(pattern) { excluded=true; break; }
                }
            }
            if excluded { continue; }
            if !cli.include_hidden {
                if trimmed.split('/').any(|comp| comp.starts_with('.') && comp!="." && comp!="..") { continue; }
            }
            *file_counts.entry(trimmed.to_string()).or_insert(0)+=1;
        }
    }
    let mut churns: Vec<FileChurn> = file_counts.into_iter().map(|(path,cnt)| FileChurn { filePath: path, nbrOfCommits: cnt }).collect();
    churns.sort_by(|a,b| b.nbrOfCommits.cmp(&a.nbrOfCommits).then(a.filePath.cmp(&b.filePath)));
    let limited = churns.into_iter().take(cli.number_of_file_churns).collect();
    ChurnInfo { file_churns: limited, churn_pool_size: pool_size }
}
fn get_loc_and_size(repo_root: &Path, cli: &ParsedCli) -> (usize, String, usize) {
    let files = collect_files(repo_root, cli);
    let mut total_loc=0;
    let mut total_size: u64 = 0;
    let mut file_count=0;
    for file_path in &files {
        if let Some(_lang)=detect_language(file_path) {
            if let Ok(content)=fs::read_to_string(file_path) {
                let loc = content.lines().filter(|l| !l.trim().is_empty()).count();
                total_loc+=loc;
            }
        }
        if let Ok(metadata)=fs::metadata(file_path) {
            total_size+=metadata.len();
            file_count+=1;
        }
    }
    let size_str = format_size(total_size);
    (total_loc, size_str, file_count)
}
fn format_size(bytes: u64) -> String {
    if bytes < 1024 { format!("{} B", bytes) }
    else if bytes < 1024*1024 { format!("{:.2} KiB", bytes as f64/1024.0) }
    else if bytes < 1024*1024*1024 { format!("{:.2} MiB", bytes as f64/(1024.0*1024.0)) }
    else { format!("{:.2} GiB", bytes as f64/(1024.0*1024.0*1024.0)) }
}
fn print_text_output(info: &OutputInfo, cli: &ParsedCli) {
    let mut output = String::new();
    if let Some(ref title)=info.title {
        let bold_code = if cli.no_bold { "" } else { ";1" };
        let color = get_dominant_color(info);
        if !cli.no_bold {
            output.push_str(&format!("\x1b[?7l\x1b[{}{}m{}\x1b[0m \x1b[39;1m~\x1b[0m \x1b[{}{}m{}\x1b[0m\n", color, bold_code, title.gitUsername, color, bold_code, title.gitVersion));
        } else {
            output.push_str(&format!("\x1b[?7l\x1b[{}m{}\x1b[0m \x1b[39m~\x1b[0m \x1b[{}m{}\x1b[0m\n", color, title.gitUsername, color, title.gitVersion));
        }
        output.push_str("\x1b[39m------------------------------\x1b[39m\n");
    } else {
        output.push_str("\x1b[?7l");
    }

    for field in &info.infoFields {
        match field {
            InfoField::ProjectInfo(p) => {
                if p.repoName.is_empty() { continue; }
                let mut proj_str = p.repoName.clone();
                if p.numberOfBranches>0 || p.numberOfTags>0 {
                    let mut parts = Vec::new();
                    if p.numberOfBranches>0 { parts.push(format!("{} branches", p.numberOfBranches)); }
                    if p.numberOfTags>0 { parts.push(format!("{} tags", p.numberOfTags)); }
                    proj_str = format!("{} ({})", proj_str, parts.join(", "));
                }
                output.push_str(&format_field("Project", &proj_str, cli));
            },
            InfoField::DescriptionInfo(d) => {
                if let Some(ref desc)=d.description {
                    output.push_str(&format_field("Description", desc, cli));
                }
            },
            InfoField::HeadInfo(h) => {
                let mut head_str = h.headRefs.shortCommitId.clone();
                if !h.headRefs.refs.is_empty() {
                    head_str = format!("{} ({})", head_str, h.headRefs.refs.join(", "));
                }
                output.push_str(&format_field("HEAD", &head_str, cli));
            },
            InfoField::PendingInfo(p) => {
                if p.added==0 && p.deleted==0 && p.modified==0 { continue; }
                let mut pend_str = String::new();
                if p.added>0 { pend_str.push_str(&format!("{}+ ", p.added)); }
                if p.deleted>0 { pend_str.push_str(&format!("{}- ", p.deleted)); }
                if p.modified>0 { pend_str.push_str(&format!("{}~ ", p.modified)); }
                let pend_str = pend_str.trim().to_string();
                if pend_str.is_empty() { continue; }
                output.push_str(&format_field("Pending", &pend_str, cli));
            },
            InfoField::VersionInfo(v) => {
                if v.version.is_empty() { continue; }
                output.push_str(&format_field("Version", &v.version, cli));
            },
            InfoField::CreatedInfo(c) => {
                output.push_str(&format_field("Created", &c.creationDate, cli));
            },
            InfoField::LanguagesInfo(l) => {
                if l.languagesWithPercentage.is_empty() { continue; }
                let langs_str = l.languagesWithPercentage.iter().map(|lp| format!("{} ({:.1} %)", lp.language, lp.percentage)).collect::<Vec<_>>().join(" ");
                output.push_str(&format_field("Language", &langs_str, cli));
            },
            InfoField::DependenciesInfo(d) => {
                if d.dependencies.is_empty() { continue; }
                output.push_str(&format_field("Dependencies", &d.dependencies, cli));
            },
            InfoField::AuthorsInfo(a) => {
                if a.authors.is_empty() { continue; }
                for (i, author) in a.authors.iter().enumerate() {
                    let author_str = if let Some(ref email)=author.email {
                        format!("{}% {} <{}> {}", author.contribution, author.name, email, author.nbrOfCommits)
                    } else {
                        format!("{}% {} {}", author.contribution, author.name, author.nbrOfCommits)
                    };
                    if i==0 {
                        output.push_str(&format_field("Author", &author_str, cli));
                    } else {
                        output.push_str(&format!("{}{}\n", " ".repeat(10), author_str));
                    }
                }
            },
            InfoField::LastChangeInfo(l) => {
                output.push_str(&format_field("Last change", &l.lastChange, cli));
            },
            InfoField::ContributorsInfo(c) => {
                if c.totalNumberOfAuthors > cli.number_of_authors {
                    output.push_str(&format_field("Contributors", &c.totalNumberOfAuthors.to_string(), cli));
                }
            },
            InfoField::UrlInfo(u) => {
                if u.repoUrl.is_empty() { continue; }
                output.push_str(&format_field("URL", &u.repoUrl, cli));
            },
            InfoField::CommitsInfo(c) => {
                output.push_str(&format_field("Commits", &c.numberOfCommits.to_string(), cli));
            },
            InfoField::ChurnInfo(ch) => {
                if ch.file_churns.is_empty() { continue; }
                let first = &ch.file_churns[0];
                output.push_str(&format_field(&format!("Churn ({})", ch.churn_pool_size), &format!("{} {}", first.filePath, first.nbrOfCommits), cli));
                for fc in ch.file_churns.iter().skip(1) {
                    output.push_str(&format!("{}{} {}\n", " ".repeat(12), fc.filePath, fc.nbrOfCommits));
                }
            },
            InfoField::LocInfo(l) => {
                let loc_str = format_number(l.linesOfCode, &cli.number_separator);
                output.push_str(&format_field("Lines of code", &loc_str, cli));
            },
            InfoField::SizeInfo(s) => {
                let size_str = format!("{} ({} files)", s.repoSize, format_number(s.fileCount, &cli.number_separator));
                output.push_str(&format_field("Size", &size_str, cli));
            },
            InfoField::LicenseInfo(l) => {
                if l.license.is_empty() { continue; }
                output.push_str(&format_field("License", &l.license, cli));
            },
        }
    }

    output.push_str("\x1b[?7h");
    print!("{}", output);
}

fn format_field(title: &str, value: &str, cli: &ParsedCli) -> String {
    let bold = if cli.no_bold { "" } else { ";1" };
    let color = 37;
    if !cli.no_bold {
        format!("\x1b[{}{}m{}\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m\n", color, bold, title, value)
    } else {
        format!("\x1b[{}m{}\x1b[0m\x1b[39m:\x1b[0m \x1b[39m{}\x1b[0m\n", color, title, value)
    }
}
fn get_dominant_color(info: &OutputInfo) -> u8 {
    for field in &info.infoFields {
        if let InfoField::LanguagesInfo(l)=field {
            if let Some(first)=l.languagesWithPercentage.first() {
                return match first.language.as_str() {
                    "Rust"=>31,"Python"=>34,"JavaScript"=>33,"Go"=>36,"Java"=>31,"C"=>35,"Cpp"=>34,_=>37,
                }
            }
        }
    }
    37
}
fn format_number(num: usize, sep: &str) -> String {
    let s = num.to_string();
    match sep {
        "comma" => {
            let mut res=String::new(); let mut count=0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 { res.push(','); }
                res.push(c); count+=1;
            }
            res.chars().rev().collect()
        },
        "space" => {
            let mut res=String::new(); let mut count=0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 { res.push(' '); }
                res.push(c); count+=1;
            }
            res.chars().rev().collect()
        },
        "underscore" => {
            let mut res=String::new(); let mut count=0;
            for c in s.chars().rev() {
                if count!=0 && count%3==0 { res.push('_'); }
                res.push(c); count+=1;
            }
            res.chars().rev().collect()
        },
        _=>s,
    }
}
