                    let mut top: Vec<LanguagePercentage> = l.languagesWithPercentage.iter().take(cli.number_of_languages).cloned().collect();
                    let remaining_perc: f64 = l.languagesWithPercentage.iter().skip(cli.number_of_languages).map(|lp| lp.percentage).sum();
                    if remaining_perc > 0.0 {
                        top.push(LanguagePercentage { language: "Other".to_string(), percentage: remaining_perc });
                    }
                    top
                } else {
                    l.languagesWithPercentage.clone()
                };
                let lang_key = if display_langs.len() == 1 { "Language" } else { "Languages" };
                let langs_str = display_langs.iter().map(|lp| format!("{} ({:.1} %)", lp.language, lp.percentage)).collect::<Vec<_>>().join(" ");
                output.push_str(&format_field(lang_key, &langs_str, cli));
            },'''

p=p.replace(old_print, new_print)
